mapper.select:
select
    case when sum(cl.credit) = 0 then null
         else round(sum(gr.grade_point * cl.credit) / sum(cl.credit), 2)
    end as gpa
from aem_grade_record gr
left join tpm_course_library cl on gr.course_id = cl.course_id
where gr.student_id = #{studentId}

      and gr.semester_id = #{semesterId}

  and gr.status = '0'

select coalesce(sum(cl.credit), 0) from aem_grade_record gr left join tpm_course_library cl on gr.course_id = cl.course_id where gr.student_id = #{studentId}
and gr.semester_id = #{semesterId}
and gr.is_pass = '1' and gr.status = '0'

select coalesce(sum(cl.credit), 0)
from aem_grade_record gr
left join tpm_course_library cl on gr.course_id = cl.course_id
where gr.student_id = #{studentId}

      and gr.semester_id = #{semesterId}

  and gr.status = '0'

select count(1)
from aem_grade_record gr
where gr.student_id = #{studentId}

      and gr.semester_id = #{semesterId}

  and gr.is_pass = '0'
  and gr.status = '0'

select count(1)
from aem_grade_record gr
left join tpm_course_library cl on gr.course_id = cl.course_id
where gr.student_id = #{studentId}

      and gr.semester_id = #{semesterId}

  and gr.is_pass = '0'
  and gr.status = '0'

      and cl.course_category = #{category}

select count(1) from aem_grade_record gr left join tpm_course_library cl on gr.course_id = cl.course_id where gr.student_id = #{studentId}
and gr.semester_id = #{semesterId}
and gr.is_pass = '0' and gr.status = '0' and cl.course_name like concat('%', #{keyword}, '%')

select count(1) from aem_grade_record gr left join tpm_course_library cl on gr.course_id = cl.course_id where gr.student_id = #{studentId}
and gr.semester_id = #{semesterId}
and gr.is_pass = '0' and gr.status = '0' and cl.course_type = '必修'
